// File: result.go
// Responsibility: Represent one converted value and the complete conversion result set.
// Receives: Raw numeric values generated by the conversion engine.
// Produces: Structured results for the formatter/presenter.
// Previous logical stage: conversion/engine.go.
// Next logical stage: output/formatter.go.
// Important restrictions: Values remain unrounded here; formatting owns visible precision.
package model

type ConvertedValue struct {
	Name   string
	Symbol string
	Value  float64
}

type ConversionResult struct {
	Family    string
	Magnitude string
	Input     ConvertedValue
	Values    []ConvertedValue
}
